update dh_import_job
dataset_id = #{datasetId}, status = #{status}, phase = #{phase}, sheet_name = #{sheetName}, proposed_display_name = #{proposedDisplayName}, proposed_physical_name = #{proposedPhysicalName}, schema_snapshot_json = #{schemaSnapshotJson}, staging_table_name = #{stagingTableName}, target_table_name = #{targetTableName}, total_rows = #{totalRows}, processed_rows = #{processedRows}, success_rows = #{successRows}, failed_rows = #{failedRows}, error_message = #{errorMessage}, start_time = #{startTime}, finish_time = #{finishTime}, update_time = sysdate(3)
where job_id = #{jobId} and lock_version = #{lockVersion}

update dh_import_job set update_time = sysdate(3)
where job_id = #{jobId} and lock_version = #{lockVersion}
  and status in ('VALIDATING', 'STAGING', 'COMMITTING')

