    row_count, column_count, status, source_file_name, source_sheet_name,
    lock_version, del_flag, create_by, create_time, update_by, update_time, remark
) values (
    #{displayName}, #{normalizedName}, #{datasetCode}, #{ownerUserId}, #{ownerUserName},
    #{rowCount}, #{columnCount}, #{status}, #{sourceFileName}, #{sourceSheetName},
    0, '0', #{createBy}, sysdate(3), #{updateBy}, sysdate(3), #{remark}
)

